# Code generated by Claude
"""
Updates the staleness stamp of the existing reach maps deliberately (decisions-log M160), keeping every voxel.

    MUJOCO_GL=egl python experiments/reach_map_restamp.py [--dir data/reach_map] [--check]

The stamp (experiments/reach_map_build.stamp_of) hashes the robot's bodies and geoms, the grasp settings and the sampler version. The neck is gone (M153) and the eagle camera's box is new, so the
stamp of the current model differs from the maps' stamp. The maps were built with the neck at its drive pose as an obstacle of the arm collision filter; without it the reachable set can only
grow, so they stay valid (safe, slightly conservative) and are NOT rebuilt (David, 2026-10-22, A3). Each map is rewritten (a temporary file, read back and compared, then renamed over the old one;
an interrupted run leaves the old file) with the new stamp and, in its info, {"restamp": {"old", "new", "reason", "date"}}; build_summary.json gets a "restamp" entry.
--check only reports (exit 1 if a map's stamp differs from the current model's).
"""

import argparse
import json
import os
import sys
import time
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))
sys.path.insert(0, str(PROJECT_ROOT / "experiments"))
if not os.environ.get("DISPLAY"):
    os.environ.setdefault("MUJOCO_GL", "egl")

import numpy as np  # noqa: E402

from reach_map_build import stamp_of  # noqa: E402
from src.gripper_geometry import grasp_cfg  # noqa: E402
from src.task_beaker_hotplate import load_task  # noqa: E402

REASON = ("the SO-101 neck was removed from the model and the eagle camera's box added (design plan 14, M153, M158); the maps were built with the neck as an obstacle of the arm collision filter, "
          "so without it they are safe and slightly conservative; accepted, not rebuilt (David 2026-10-22, A3, M160)")


def main(args):
    sim = load_task(cameras=False)
    m = sim.model
    folder = Path(args.dir)
    stamps = {side: stamp_of(m, {k: v for k, v in grasp_cfg(m, side).items() if k != "quick_samples"}) for side in ("left", "right")}
    changed, same = [], []
    for f in sorted(folder.glob("*_bin*.npz")):
        z = np.load(f)
        old, side = str(z["stamp"]), str(z["side"])
        (same if old == stamps[side] else changed).append((f, old, side))
    print(f"current stamps {stamps}; {len(same)} maps current, {len(changed)} maps with another stamp")
    if args.check:
        return not changed
    summary_path = folder / "build_summary.json"
    for f, old, side in changed:
        z = dict(np.load(f))
        info = json.loads(str(z["info"]))
        info["restamp"] = {"old": old, "new": stamps[side], "reason": REASON, "date": time.strftime("%Y-%m-%d")}
        z["stamp"], z["info"] = np.array(stamps[side]), np.array(json.dumps(info))
        tmp = str(f) + ".tmp"
        with open(tmp, "wb") as fh:
            np.savez_compressed(fh, **z)
        a, b = np.load(f), np.load(tmp)
        assert all(np.array_equal(a[k], b[k]) for k in ("reached", "shape", "origin", "voxel", "side", "bin")) and str(b["stamp"]) == stamps[side]     # every voxel unchanged
        a.close(), b.close()
        os.replace(tmp, f)
        print(f"  {f.name}: stamp {old} -> {stamps[side]}")
    if changed:
        summary = json.loads(summary_path.read_text()) if summary_path.exists() else {}
        summary["restamp"] = {"date": time.strftime("%Y-%m-%d"), "reason": REASON, "stamps": stamps, "maps": [f.name for f, _, _ in changed]}
        tmp = str(summary_path) + ".tmp"
        Path(tmp).write_text(json.dumps(summary, indent=1, default=str))
        os.replace(tmp, summary_path)
    return True


if __name__ == "__main__":
    ap = argparse.ArgumentParser()
    ap.add_argument("--dir", default=str(PROJECT_ROOT / "data" / "reach_map"))
    ap.add_argument("--check", action="store_true")
    sys.exit(0 if main(ap.parse_args()) else 1)
